int rueckgabeGebuehr(int tage) {
    if (tage < 0) {
        return -1;
    }
    int gebuehr = 0;
    if (tage > 0) {
        gebuehr = 4;
    }
    if (tage > 3) {
        gebuehr = gebuehr + (tage - 3) * 3;
    }
    return gebuehr;
}

int rabattProzent(int warenwert) {
    int rabatt = 0;
    if (warenwert < 0) {
        return -1;
    }
    if (warenwert > 100) {
        rabatt = 5;
    }
    if (warenwert > 500) {
        rabatt = 10;
    }
    return rabatt;
}

int reserviere(int bestand, int menge) {
    if (bestand < 0 || menge <= 0) {
        return -1;
    }
    if (menge < bestand) {
        return bestand - menge;
    }
    return -2;
}
